1	import { useState, useRef } from "react";
2	import { useParams, Link } from "react-router-dom";
3	import { useQuery } from "@tanstack/react-query";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Button } from "@/components/ui/button";
6	import { Input } from "@/components/ui/input";
7	import { Label } from "@/components/ui/label";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { toast } from "sonner";
10	import {
11	  CheckCircle2,
12	  Upload,
13	  FileText,
14	  X,
15	  Loader2,
16	  ExternalLink,
17	  Briefcase,
18	} from "lucide-react";
19	
20	const MAX_FILE_BYTES = 10 * 1024 * 1024; // 10 MB
21	const ALLOWED_EXTENSIONS = [".pdf", ".docx", ".doc", ".rtf", ".txt"];
22	const ALLOWED_MIME = [
23	  "application/pdf",
24	  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
25	  "application/msword",
26	  "text/plain",
27	  "application/rtf",
28	  "text/rtf",
29	];
30	
31	function hasAllowedExtension(filename: string): boolean {
32	  const lower = filename.toLowerCase();
33	  return ALLOWED_EXTENSIONS.some((ext) => lower.endsWith(ext));
34	}
35	
36	interface JobInfo {
37	  id: string;
38	  title: string;
39	  status: string;
40	  job_description: string;
41	}
42	
43	export default function Apply() {
44	  const { jobId } = useParams<{ jobId: string }>();
45	  const fileInputRef = useRef<HTMLInputElement>(null);
46	
47	  const [name, setName] = useState("");
48	  const [email, setEmail] = useState("");
49	  const [phone, setPhone] = useState("");
50	  const [linkedinUrl, setLinkedinUrl] = useState("");
51	  const [resumeFile, setResumeFile] = useState<File | null>(null);
52	  const [dragOver, setDragOver] = useState(false);
53	  const [submitting, setSubmitting] = useState(false);
54	  const [submitted, setSubmitted] = useState(false);
55	  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
56	
57	  // Fetch minimal job info — no auth required via RPC
58	  const {
59	    data: job,
60	    isLoading: jobLoading,
61	    error: jobError,
62	  } = useQuery<JobInfo | null>({
63	    queryKey: ["apply-job-info", jobId],
64	    queryFn: async () => {
65	      if (!jobId) return null;
66	      const { data, error } = await supabase.rpc("get_job_apply_info", {
67	        p_job_id: jobId,
68	      });
69	      if (error) throw new Error(error.message);
70	      if (!data || (Array.isArray(data) && data.length === 0)) return null;
71	      const row = Array.isArray(data) ? data[0] : data;
72	      return row as JobInfo;
73	    },
74	    enabled: !!jobId,
75	    retry: 1,
76	    staleTime: 60_000,
77	  });
78	
79	  const handleFileSelect = (file: File) => {
80	    if (file.size > MAX_FILE_BYTES) {
81	      toast.error("File exceeds 10MB limit");
82	      return;
83	    }
84	    if (!ALLOWED_MIME.includes(file.type) && !hasAllowedExtension(file.name)) {
85	      toast.error("Please upload a PDF, DOCX, DOC, RTF, or TXT file");
86	      return;
87	    }
88	    setResumeFile(file);
89	    setFieldErrors((prev) => ({ ...prev, resume: "" }));
90	  };
91	
92	  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
93	    e.preventDefault();
94	    setDragOver(false);
95	    const file = e.dataTransfer.files[0];
96	    if (file) handleFileSelect(file);
97	  };
98	
99	  const validate = (): boolean => {
100	    const errors: Record<string, string> = {};
101	    if (!name.trim()) errors.name = "Name is required";
102	    if (!email.trim()) errors.email = "Email is required";
103	    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))
104	      errors.email = "Enter a valid email address";
105	    setFieldErrors(errors);
106	    return Object.keys(errors).length === 0;
107	  };
108	
109	  const handleSubmit = async (e: React.FormEvent) => {
110	    e.preventDefault();
111	    if (!validate()) return;
112	    if (!jobId) {
113	      toast.error("Invalid application link");
114	      return;
115	    }
116	
117	    setSubmitting(true);
118	    try {
119	      const form = new FormData();
120	      form.append("job_id", jobId);
121	      form.append("name", name.trim());
122	      form.append("email", email.trim().toLowerCase());
123	      if (phone.trim()) form.append("phone", phone.trim());
124	      if (linkedinUrl.trim()) form.append("linkedin_url", linkedinUrl.trim());
125	      if (resumeFile) form.append("resume", resumeFile);
126	
127	      const { data: sessionData } = await supabase.auth.getSession();
128	      const headers: Record<string, string> = {
129	        // Supabase project URL and anon key from env — required even for anon calls
130	        apikey: import.meta.env.VITE_SUPABASE_ANON_KEY as string,
131	      };
132	      if (sessionData.session?.access_token) {
133	        headers["Authorization"] = `Bearer ${sessionData.session.access_token}`;
134	      } else {
135	        headers["Authorization"] = `Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY as string}`;
136	      }
137	
138	      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
139	      const res = await fetch(
140	        `${supabaseUrl}/functions/v1/submit-application`,
141	        {
142	          method: "POST",
143	          headers,
144	          body: form,
145	        }
146	      );
147	
148	      const json = await res.json();
149	      if (!res.ok) {
150	        throw new Error(json.error || "Failed to submit application");
151	      }
152	
153	      setSubmitted(true);
154	    } catch (err: unknown) {
155	      const message =
156	        err instanceof Error ? err.message : "Submission failed. Please try again.";
157	      toast.error(message);
158	    } finally {
159	      setSubmitting(false);
160	    }
161	  };
162	
163	  // ── Success screen ──────────────────────────────────────────────────────
164	  if (submitted) {
165	    return (
166	      <div className="min-h-screen bg-background flex flex-col">
167	        <ApplyHeader />
168	        <main className="flex-1 flex items-center justify-center px-4 py-16">
169	          <div className="w-full max-w-md text-center space-y-6">
170	            <div className="flex justify-center">
171	              <div className="w-16 h-16 rounded-full bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center">
172	                <CheckCircle2 className="h-8 w-8 text-emerald-600 dark:text-emerald-400" />
173	              </div>
174	            </div>
175	            <div className="space-y-2">
176	              <h1 className="text-2xl font-semibold tracking-tight">
177	                Application Submitted Successfully!
178	              </h1>
179	              <p className="text-sm text-muted-foreground leading-relaxed">
180	                Thank you! We will review your information and get in touch shortly.
181	              </p>
182	            </div>
183	            <Link
184	              to="/"
185	              className="inline-flex items-center gap-2 text-sm font-medium text-primary hover:text-primary/80 transition-colors"
186	            >
187	              Back to Jobs
188	            </Link>
189	          </div>
190	        </main>
191	        <ApplyFooter />
192	      </div>
193	    );
194	  }
195	
196	  // ── Job not found ───────────────────────────────────────────────────────
197	  // Note: status === "failed" means the ranking pipeline failed, NOT that the
198	  // job is closed for applications. We don't block applications on failed jobs.
199	  if (!jobLoading && (jobError || !job)) {
200	    return (
201	      <div className="min-h-screen bg-background flex flex-col">
202	        <ApplyHeader />
203	        <main className="flex-1 flex items-center justify-center px-4 py-16">
204	          <div className="w-full max-w-md text-center space-y-4">
205	            <div className="flex justify-center">
206	              <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center">
207	                <Briefcase className="h-7 w-7 text-muted-foreground" />
208	              </div>
209	            </div>
210	            <h1 className="text-xl font-semibold">Job not found</h1>
211	            <p className="text-sm text-muted-foreground">
212	              This application link may have expired or the job no longer exists.
213	            </p>
214	            <Link
215	              to="/"
216	              className="inline-flex items-center gap-2 text-sm font-medium text-primary hover:text-primary/80 transition-colors"
217	            >
218	              Back to Jobs
219	            </Link>
220	          </div>
221	        </main>
222	        <ApplyFooter />
223	      </div>
224	    );
225	  }
226	
227	  return (
228	    <div className="min-h-screen bg-background flex flex-col">
229	      <ApplyHeader />
230	
231	      <main className="flex-1 flex items-start justify-center px-4 py-10">
232	        <div className="w-full max-w-lg">
233	          {/* Job title */}
234	          <div className="mb-8 space-y-1">
235	            {jobLoading ? (
236	              <>
237	                <Skeleton className="h-7 w-64" />
238	                <Skeleton className="h-4 w-40 mt-2" />
239	              </>
240	            ) : (
241	              <>
242	                <h1 className="text-2xl font-semibold tracking-tight leading-tight">
243	                  {job?.title ?? "Apply for this position"}
244	                </h1>
245	                {job?.job_description && (
246	                  <div className="mt-4 rounded-lg border border-border bg-muted/30 p-4 max-h-60 overflow-y-auto">
247	                    <h2 className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2">
248	                      Job Description
249	                    </h2>
250	                    <p className="text-sm text-foreground whitespace-pre-line leading-relaxed">
251	                      {job.job_description}
252	                    </p>
253	                  </div>
254	                )}
255	                <p className="text-sm text-muted-foreground mt-3">
256	                  Fill in your details below to apply.
257	                </p>
258	              </>
259	            )}
260	          </div>
261	
262	          <form onSubmit={handleSubmit} noValidate className="space-y-5">
263	            {/* Name */}
264	            <div className="space-y-1.5">
265	              <Label htmlFor="apply-name">
266	                Full Name <span className="text-destructive">*</span>
267	              </Label>
268	              <Input
269	                id="apply-name"
270	                type="text"
271	                placeholder="Jane Smith"
272	                value={name}
273	                onChange={(e) => {
274	                  setName(e.target.value);
275	                  if (fieldErrors.name)
276	                    setFieldErrors((prev) => ({ ...prev, name: "" }));
277	                }}
278	                autoComplete="name"
279	                aria-invalid={!!fieldErrors.name}
280	                aria-describedby={fieldErrors.name ? "name-error" : undefined}
281	                disabled={submitting}
282	              />
283	              {fieldErrors.name && (
284	                <p id="name-error" className="text-xs text-destructive">
285	                  {fieldErrors.name}
286	                </p>
287	              )}
288	            </div>
289	
290	            {/* Email */}
291	            <div className="space-y-1.5">
292	              <Label htmlFor="apply-email">
293	                Email Address <span className="text-destructive">*</span>
294	              </Label>
295	              <Input
296	                id="apply-email"
297	                type="email"
298	                placeholder="jane@example.com"
299	                value={email}
300	                onChange={(e) => {
301	                  setEmail(e.target.value);
302	                  if (fieldErrors.email)
303	                    setFieldErrors((prev) => ({ ...prev, email: "" }));
304	                }}
305	                autoComplete="email"
306	                aria-invalid={!!fieldErrors.email}
307	                aria-describedby={fieldErrors.email ? "email-error" : undefined}
308	                disabled={submitting}
309	              />
310	              {fieldErrors.email && (
311	                <p id="email-error" className="text-xs text-destructive">
312	                  {fieldErrors.email}
313	                </p>
314	              )}
315	            </div>
316	
317	            {/* Phone */}
318	            <div className="space-y-1.5">
319	              <Label htmlFor="apply-phone">Phone Number</Label>
320	              <Input
321	                id="apply-phone"
322	                type="tel"
323	                placeholder="+1 555 000 0000"
324	                value={phone}
325	                onChange={(e) => setPhone(e.target.value)}
326	                autoComplete="tel"
327	                disabled={submitting}
328	              />
329	            </div>
330	
331	            {/* Resume Upload */}
332	            <div className="space-y-1.5">
333	              <Label>Resume / CV <span className="text-xs font-normal text-muted-foreground">(optional)</span></Label>
334	              {resumeFile ? (
335	                <div className="flex items-center gap-3 rounded-lg border border-border bg-secondary/40 px-4 py-3">
336	                  <FileText className="h-5 w-5 text-primary shrink-0" />
337	                  <span className="flex-1 text-sm truncate">{resumeFile.name}</span>
338	                  <button
339	                    type="button"
340	                    onClick={() => {
341	                      setResumeFile(null);
342	                      if (fileInputRef.current) fileInputRef.current.value = "";
343	                    }}
344	                    className="text-muted-foreground hover:text-destructive transition-colors"
345	                    aria-label="Remove resume"
346	                    disabled={submitting}
347	                  >
348	                    <X className="h-4 w-4" />
349	                  </button>
350	                </div>
351	              ) : (
352	                <div
353	                  role="button"
354	                  tabIndex={0}
355	                  aria-label="Upload resume — PDF, DOCX, DOC, RTF, or TXT, max 10MB"
356	                  onKeyDown={(e) => {
357	                    if (e.key === "Enter" || e.key === " ")
358	                      fileInputRef.current?.click();
359	                  }}
360	                  className={`border-2 border-dashed rounded-lg p-6 text-center cursor-pointer transition-all duration-200 flex flex-col items-center gap-2 focus:outline-none focus-visible:ring-2 focus-visible:ring-ring ${
361	                    dragOver
362	                      ? "border-primary bg-primary/5 scale-[1.01]"
363	                      : "border-border hover:border-primary/50 hover:bg-primary/[0.02]"
364	                  }`}
365	                  onDragOver={(e) => {
366	                    e.preventDefault();
367	                    setDragOver(true);
368	                  }}
369	                  onDragLeave={() => setDragOver(false)}
370	                  onDrop={handleDrop}
371	                  onClick={() => fileInputRef.current?.click()}
372	                >
373	                  <div className="w-10 h-10 rounded-lg bg-muted flex items-center justify-center">
374	                    <Upload className="h-5 w-5 text-primary" />
375	                  </div>
376	                  <p className="text-sm font-medium text-foreground">
377	                    Drop your resume here or{" "}
378	                    <span className="text-primary">click to browse</span>
379	                  </p>
380	                  <p className="text-xs text-muted-foreground">
381	                    PDF, DOCX, DOC, RTF, TXT · Max 10MB
382	                  </p>
383	                  <input
384	                    ref={fileInputRef}
385	                    id="resume-input"
386	                    type="file"
387	                    className="hidden"
388	                    accept=".pdf,.docx,.doc,.rtf,.txt"
389	                    onChange={(e) => {
390	                      const file = e.target.files?.[0];
391	                      if (file) handleFileSelect(file);
392	                    }}
393	                    disabled={submitting}
394	                  />
395	                </div>
396	              )}
397	            </div>
398	
399	            {/* LinkedIn URL */}
400	            <div className="space-y-1.5">
401	              <Label htmlFor="apply-linkedin" className="flex items-center gap-1.5">
402	                LinkedIn Profile
403	                <span className="text-xs font-normal text-muted-foreground">
404	                  (optional)
405	                </span>
406	              </Label>
407	              <div className="relative">
408	                <Input
409	                  id="apply-linkedin"
410	                  type="url"
411	                  placeholder="https://linkedin.com/in/jane-smith"
412	                  value={linkedinUrl}
413	                  onChange={(e) => setLinkedinUrl(e.target.value)}
414	                  className="pr-9"
415	                  disabled={submitting}
416	                />
417	                <ExternalLink className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
418	              </div>
419	            </div>
420	
421	            {/* Privacy notice */}
422	            <p className="text-[11px] text-muted-foreground/60 leading-relaxed">
423	              By submitting this application, you consent to your information being processed for recruitment purposes by the hiring company.
424	            </p>
425	
426	            {/* Submit */}
427	            <Button
428	              type="submit"
429	              className="w-full gap-2"
430	              size="lg"
431	              disabled={submitting}
432	            >
433	              {submitting ? (
434	                <>
435	                  <Loader2 className="h-4 w-4 animate-spin" />
436	                  Submitting…
437	                </>
438	              ) : (
439	                "Submit Application"
440	              )}
441	            </Button>
442	          </form>
443	        </div>
444	      </main>
445	
446	      <ApplyFooter />
447	    </div>
448	  );
449	}
450	
451	function ApplyHeader() {
452	  return (
453	    <header className="sticky top-0 z-10 bg-background/95 backdrop-blur border-b border-border">
454	      <div className="max-w-2xl mx-auto px-4 py-4 flex items-center gap-2">
455	        <Link
456	          to="/"
457	          className="flex items-center gap-2 text-sm font-semibold text-foreground hover:text-primary transition-colors"
458	        >
459	          <div className="w-6 h-6 rounded bg-primary flex items-center justify-center">
460	            <span className="text-[11px] font-bold text-primary-foreground">R</span>
461	          </div>
462	          Rankora
463	        </Link>
464	      </div>
465	    </header>
466	  );
467	}
468	
469	function ApplyFooter() {
470	  return (
471	    <footer className="py-6 text-center">
472	      <p className="text-xs text-muted-foreground">
473	        Powered by{" "}
474	        <Link to="/" className="text-primary font-medium hover:text-primary/80 transition-colors">
475	          Rankora
476	        </Link>
477	      </p>
478	    </footer>
479	  );
480	}
