1	import { useState, useEffect } from "react";
2	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
3	import { supabase } from "@/integrations/supabase/client";
4	import { Button } from "@/components/ui/button";
5	import { Badge } from "@/components/ui/badge";
6	import { Skeleton } from "@/components/ui/skeleton";
7	import {
8	  Select,
9	  SelectContent,
10	  SelectItem,
11	  SelectTrigger,
12	  SelectValue,
13	} from "@/components/ui/select";
14	import {
15	  Table,
16	  TableBody,
17	  TableCell,
18	  TableHead,
19	  TableHeader,
20	  TableRow,
21	} from "@/components/ui/table";
22	import { toast } from "sonner";
23	import {
24	  Download,
25	  ExternalLink,
26	  Users,
27	  Loader2,
28	  FileText,
29	} from "lucide-react";
30	
31	type ApplicationStatus = "pending" | "reviewed" | "shortlisted" | "rejected";
32	
33	interface Application {
34	  id: string;
35	  job_id: string;
36	  name: string;
37	  email: string;
38	  phone: string | null;
39	  linkedin_url: string | null;
40	  resume_path: string | null;
41	  resume_filename: string | null;
42	  status: ApplicationStatus;
43	  created_at: string;
44	}
45	
46	const STATUS_LABELS: Record<ApplicationStatus, string> = {
47	  pending: "Pending",
48	  reviewed: "Reviewed",
49	  shortlisted: "Shortlisted",
50	  rejected: "Rejected",
51	};
52	
53	const STATUS_COLORS: Record<ApplicationStatus, string> = {
54	  pending: "bg-muted text-muted-foreground",
55	  reviewed: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
56	  shortlisted:
57	    "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400",
58	  rejected:
59	    "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
60	};
61	
62	interface ApplicationsTabProps {
63	  jobId: string;
64	}
65	
66	export default function ApplicationsTab({ jobId }: ApplicationsTabProps) {
67	  const queryClient = useQueryClient();
68	  const [updatingId, setUpdatingId] = useState<string | null>(null);
69	
70	  const {
71	    data: applications,
72	    isLoading,
73	    error,
74	  } = useQuery<Application[]>({
75	    queryKey: ["applications", jobId],
76	    queryFn: async () => {
77	      const { data, error } = await supabase
78	        .from("applications")
79	        .select(
80	          "id, job_id, name, email, phone, linkedin_url, resume_path, resume_filename, status, created_at"
81	        )
82	        .eq("job_id", jobId)
83	        .order("created_at", { ascending: false });
84	      if (error) throw new Error(error.message);
85	      return (data ?? []) as Application[];
86	    },
87	    enabled: !!jobId,
88	    staleTime: 30_000,
89	  });
90	
91	  // Realtime subscription — auto-refresh when new applications arrive
92	  useEffect(() => {
93	    const channel = supabase
94	      .channel(`applications-${jobId}`)
95	      .on(
96	        "postgres_changes",
97	        {
98	          event: "INSERT",
99	          schema: "public",
100	          table: "applications",
101	          filter: `job_id=eq.${jobId}`,
102	        },
103	        () => {
104	          queryClient.invalidateQueries({ queryKey: ["applications", jobId] });
105	        }
106	      )
107	      .subscribe();
108	
109	    return () => {
110	      supabase.removeChannel(channel);
111	    };
112	  }, [jobId, queryClient]);
113	
114	  const updateStatus = useMutation({
115	    mutationFn: async ({
116	      applicationId,
117	      newStatus,
118	    }: {
119	      applicationId: string;
120	      newStatus: ApplicationStatus;
121	    }) => {
122	      const { error } = await supabase
123	        .from("applications")
124	        .update({ status: newStatus })
125	        .eq("id", applicationId);
126	      if (error) throw new Error(error.message);
127	    },
128	    onMutate: ({ applicationId }) => setUpdatingId(applicationId),
129	    onSuccess: (_, { applicationId, newStatus }) => {
130	      queryClient.setQueryData<Application[]>(
131	        ["applications", jobId],
132	        (prev) =>
133	          (prev ?? []).map((a) =>
134	            a.id === applicationId ? { ...a, status: newStatus } : a
135	          )
136	      );
137	      toast.success(`Application marked as ${STATUS_LABELS[newStatus]}`);
138	    },
139	    onError: (err: Error) => toast.error(err.message || "Failed to update status"),
140	    onSettled: () => setUpdatingId(null),
141	  });
142	
143	  const downloadResume = async (resumePath: string, filename: string) => {
144	    const { data, error } = await supabase.storage
145	      .from("resumes")
146	      .download(resumePath);
147	    if (error || !data) {
148	      toast.error("Failed to download resume");
149	      return;
150	    }
151	    const url = URL.createObjectURL(data);
152	    const a = document.createElement("a");
153	    a.href = url;
154	    a.download = filename;
155	    a.click();
156	    URL.revokeObjectURL(url);
