169	                className="h-8 text-xs"
170	              />
171	            </div>
172	          </div>
173	          )}
174	          <Button
175	            size="sm"
176	            className="h-7 text-xs gap-1"
177	            onClick={handleSave}
178	            disabled={saving || !loaded}
179	          >
180	            {saving ? <Loader2 className="h-3 w-3 animate-spin" /> : <CheckCircle2 className="h-3 w-3" />}
181	            Save Details
182	          </Button>
183	        </div>
184	      </CollapsibleContent>
185	    </Collapsible>
186	  );
187	}
188	
189	// ─── Main Component ─────────────────────────────────────────────────────────
190	
191	interface JobDetailViewProps {
192	  selectedJobId: string | null;
193	  selectedJob: PastJob | null;
194	  results: Result[];
195	  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
196	  existingResumes: ExistingResume[];
197	  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
198	  onJobCreated: (job: PastJob) => void;
199	  onAuthRequired: () => void;
200	  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
201	  isAuthenticated?: boolean;
202	  pastJobs?: PastJob[];
203	  onBack?: () => void;
204	}
205	
206	interface UploadedFile {
207	  file: File;
208	  name: string;
209	}
210	
211	const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
212	
213	const JobDetailView = ({
214	  selectedJobId,
215	  selectedJob,
216	  results,
217	  setResults,
218	  existingResumes,
219	  setExistingResumes,
220	  onJobCreated,
221	  onAuthRequired,
222	  onJobUpdated,
223	  isAuthenticated = true,
224	  pastJobs = [],
225	  onBack,
226	}: JobDetailViewProps) => {
227	  const { user, profile, refreshProfile } = useAuth();
228	  const { data: config } = usePlatformConfig();
229	  const { team } = useTeam();
230	
231	  const [jobTitle, setJobTitle] = useState("");
232	  const [jobDescription, setJobDescription] = useState("");
233	  const [files, setFiles] = useState<UploadedFile[]>([]);
234	  const [selectedFileIndexes, setSelectedFileIndexes] = useState<Set<number>>(new Set());
235	  const [ranking, setRanking] = useState(false);
236	  const [rankingProgress, setRankingProgress] = useState(0);
237	  const [scoredCount, setScoredCount] = useState(0);
238	  const [totalToScore, setTotalToScore] = useState(0);
239	  const [selectedCandidateId, setSelectedCandidateId] = useState<string | null>(null);
240	  const [dragOver, setDragOver] = useState(false);
241	  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
242	  const [validationErrors, setValidationErrors] = useState<string[]>([]);
243	  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
244	  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
245	  const [deleting, setDeleting] = useState(false);
246	  const [analyzingJd, setAnalyzingJd] = useState(false);
247	  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(() => new Set());
248	  const [showArchived, setShowArchived] = useState(false);
249	  const [stageFilter, setStageFilter] = useState<HiringStage | null>(null);
250	  const [jdRewriteOpen, setJdRewriteOpen] = useState(false);
251	  const [stuckJobDetected, setStuckJobDetected] = useState(false);
252	  const [retrying, setRetrying] = useState(false);
253	  const [editingJd, setEditingJd] = useState(false);
254	  const [editedJdText, setEditedJdText] = useState("");
255	  const [confirmEditJdOpen, setConfirmEditJdOpen] = useState(false);
256	  const [activeTab, setActiveTab] = useState<"resumes" | "applications">("resumes");
257	  const [showGuestLink, setShowGuestLink] = useState(false);
258	
259	  const queryClient = useQueryClient();
260	
261	  // Application count for badge on Applications tab
262	  const { data: applicationCount } = useQuery<number>({
263	    queryKey: ["applications-count", selectedJobId],
264	    queryFn: async () => {
265	      if (!selectedJobId) return 0;
266	      const { count, error } = await (supabase as any)
267	        .from("applications")
268	        .select("id", { count: "exact", head: true })
269	        .eq("job_id", selectedJobId);
270	      if (error) return 0;
271	      return count ?? 0;
272	    },
273	    enabled: !!selectedJobId && !!isAuthenticated,
274	    staleTime: 30_000,
275	  });
276	
277	  // Realtime subscription — refresh application count when new applications arrive
278	  useEffect(() => {
279	    if (!selectedJobId || !isAuthenticated) return;
280	
281	    const channel = supabase
282	      .channel(`app-count-${selectedJobId}`)
283	      .on(
284	        "postgres_changes",
285	        {
286	          event: "INSERT",
287	          schema: "public",
288	          table: "applications",
289	          filter: `job_id=eq.${selectedJobId}`,
290	        },
291	        () => {
292	          queryClient.invalidateQueries({ queryKey: ["applications-count", selectedJobId] });
293	        }
294	      )
295	      .subscribe();
296	
297	    return () => {
298	      supabase.removeChannel(channel);
299	    };
