-- Custom form fields per job
CREATE TABLE public.job_form_fields (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  job_id      uuid NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE,
  field_type  text NOT NULL CHECK (field_type IN ('text', 'number', 'select', 'multiselect', 'date', 'url', 'textarea', 'checkbox')),
  label       text NOT NULL,
  placeholder text,
  required    boolean NOT NULL DEFAULT false,
  options     text[],
  sort_order  integer NOT NULL DEFAULT 0,
  is_knockout boolean NOT NULL DEFAULT false,
  knockout_answer text,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX idx_form_fields_job ON public.job_form_fields(job_id, sort_order);
ALTER TABLE public.job_form_fields ENABLE ROW LEVEL SECURITY;

-- Job owner or team member can manage form fields
CREATE POLICY "Job team can manage form fields"
  ON public.job_form_fields FOR ALL TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.jobs j
      WHERE j.id = job_form_fields.job_id AND j.user_id = auth.uid()
    )
  );

-- Public can read form fields (needed for Apply page)
CREATE POLICY "Public can view form fields"
  ON public.job_form_fields FOR SELECT TO anon
  USING (true);

-- Allow authenticated users to also read
CREATE POLICY "Auth can view form fields"
  ON public.job_form_fields FOR SELECT TO authenticated
  USING (true);

-- Store custom field responses + knockout status in applications
ALTER TABLE public.applications ADD COLUMN IF NOT EXISTS custom_fields jsonb DEFAULT '{}';
ALTER TABLE public.applications ADD COLUMN IF NOT EXISTS auto_disqualified boolean DEFAULT false;
ALTER TABLE public.applications ADD COLUMN IF NOT EXISTS disqualify_reason text;

-- Auto-ack email settings on jobs
ALTER TABLE public.jobs ADD COLUMN IF NOT EXISTS auto_ack_enabled boolean DEFAULT true;
ALTER TABLE public.jobs ADD COLUMN IF NOT EXISTS auto_ack_subject text DEFAULT 'Thank you for your application!';
ALTER TABLE public.jobs ADD COLUMN IF NOT EXISTS auto_ack_body text DEFAULT 'Thank you for applying to {{job_title}}. We have received your application and will review it shortly. We will be in touch if your profile matches our requirements.';

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { toast } from "sonner";
import {
  ChevronDown,
  Plus,
  Trash2,
  ChevronUp,
  Loader2,
  GripVertical,
  FormInput,
  X,
} from "lucide-react";

type FieldType =
  | "text"
  | "number"
  | "select"
  | "multiselect"
  | "date"
  | "url"
  | "textarea"
  | "checkbox";

interface FormField {
  id: string;
  job_id: string;
  field_type: FieldType;
  label: string;
  placeholder: string | null;
  required: boolean;
  options: string[] | null;
  sort_order: number;
  is_knockout: boolean;
  knockout_answer: string | null;
  created_at: string;
}

const FIELD_TYPE_LABELS: Record<FieldType, string> = {
  text: "Text",
  number: "Number",
  select: "Dropdown",
  multiselect: "Multi-select",
  date: "Date",
  url: "URL",
  textarea: "Long Text",
  checkbox: "Checkbox",
};

const FIELD_TYPES_WITH_OPTIONS: FieldType[] = ["select", "multiselect"];

interface AddFieldFormState {
  field_type: FieldType;
  label: string;
  placeholder: string;
  required: boolean;
  options: string;
  is_knockout: boolean;
  knockout_answer: string;
}

const DEFAULT_ADD_STATE: AddFieldFormState = {
  field_type: "text",
  label: "",
  placeholder: "",
  required: false,
  options: "",
  is_knockout: false,
  knockout_answer: "",
};

interface FormBuilderProps {
  jobId: string;
}

export default function FormBuilder({ jobId }: FormBuilderProps) {
  const [open, setOpen] = useState(false);
  const [fields, setFields] = useState<FormField[]>([]);
  const [loading, setLoading] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [showAddForm, setShowAddForm] = useState(false);
  const [addState, setAddState] = useState<AddFieldFormState>(DEFAULT_ADD_STATE);
  const [saving, setSaving] = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [movingId, setMovingId] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editState, setEditState] = useState<AddFieldFormState>(DEFAULT_ADD_STATE);

  useEffect(() => {
    if (!open || loaded) return;
    setLoading(true);
    (supabase as any)
      .from("job_form_fields")
      .select("*")
      .eq("job_id", jobId)
      .order("sort_order", { ascending: true })
      .then(({ data, error }: { data: FormField[] | null; error: any }) => {
        setLoading(false);
        if (error) {
          toast.error("Failed to load form fields");
          return;
        }
        setFields(data ?? []);
        setLoaded(true);
      });
  }, [open, jobId, loaded]);

  const handleAdd = async () => {
    if (!addState.label.trim()) {
      toast.error("Label is required");
      return;
    }
    if (
      FIELD_TYPES_WITH_OPTIONS.includes(addState.field_type) &&
      !addState.options.trim()
    ) {
      toast.error("Options are required for dropdown/multi-select fields");
      return;
    }
    if (addState.is_knockout && !addState.knockout_answer.trim()) {
      toast.error("Knockout answer is required when knockout is enabled");
      return;
    }

    setSaving(true);
    try {
      const optionsArray = FIELD_TYPES_WITH_OPTIONS.includes(addState.field_type)
        ? addState.options
            .split(",")
            .map((o) => o.trim())
            .filter(Boolean)
        : null;

      const newOrder =
        fields.length > 0 ? Math.max(...fields.map((f) => f.sort_order)) + 1 : 0;

      const payload = {
        job_id: jobId,
        field_type: addState.field_type,
        label: addState.label.trim(),
        placeholder: addState.placeholder.trim() || null,
        required: addState.required,
        options: optionsArray,
        sort_order: newOrder,
        is_knockout: addState.is_knockout,
        knockout_answer: addState.is_knockout ? addState.knockout_answer.trim() || null : null,
      };

      const { data, error } = await (supabase as any)
        .from("job_form_fields")
        .insert(payload)
        .select("*")
        .single();

      if (error) throw error;

      setFields((prev) => [...prev, data as FormField]);
      setAddState(DEFAULT_ADD_STATE);
      setShowAddForm(false);
      toast.success("Field added");
    } catch {
      toast.error("Failed to add field");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    setDeletingId(id);
    try {
      const { error } = await (supabase as any)
        .from("job_form_fields")
        .delete()
        .eq("id", id);
      if (error) throw error;
      setFields((prev) => prev.filter((f) => f.id !== id));
      toast.success("Field removed");
    } catch {
      toast.error("Failed to delete field");
    } finally {
      setDeletingId(null);
    }
  };

  const handleMove = async (id: string, direction: "up" | "down") => {
    const idx = fields.findIndex((f) => f.id === id);
    if (direction === "up" && idx === 0) return;
    if (direction === "down" && idx === fields.length - 1) return;

    const swapIdx = direction === "up" ? idx - 1 : idx + 1;
    const newFields = [...fields];
    const tempOrder = newFields[idx].sort_order;
    newFields[idx] = { ...newFields[idx], sort_order: newFields[swapIdx].sort_order };
    newFields[swapIdx] = { ...newFields[swapIdx], sort_order: tempOrder };
    [newFields[idx], newFields[swapIdx]] = [newFields[swapIdx], newFields[idx]];

    setFields(newFields);
    setMovingId(id);
    try {
      await Promise.all([
        (supabase as any)
          .from("job_form_fields")
          .update({ sort_order: newFields[idx].sort_order })
          .eq("id", newFields[idx].id),
        (supabase as any)
          .from("job_form_fields")
          .update({ sort_order: newFields[swapIdx].sort_order })
          .eq("id", newFields[swapIdx].id),
      ]);
    } catch {
      toast.error("Failed to reorder fields");
    } finally {
      setMovingId(null);
    }
  };

  const startEdit = (field: FormField) => {
    setEditingId(field.id);
    setEditState({
      field_type: field.field_type,
      label: field.label,
      placeholder: field.placeholder ?? "",
      required: field.required,
      options: field.options ? field.options.join(", ") : "",
      is_knockout: field.is_knockout,
      knockout_answer: field.knockout_answer ?? "",
    });
  };

  const handleSaveEdit = async (id: string) => {
    if (!editState.label.trim()) {
      toast.error("Label is required");
      return;
    }
    if (
      FIELD_TYPES_WITH_OPTIONS.includes(editState.field_type) &&
      !editState.options.trim()
    ) {
      toast.error("Options are required for dropdown/multi-select fields");
      return;
    }
    if (editState.is_knockout && !editState.knockout_answer.trim()) {
      toast.error("Knockout answer is required when knockout is enabled");
      return;
    }

    setSaving(true);
    try {
      const optionsArray = FIELD_TYPES_WITH_OPTIONS.includes(editState.field_type)
        ? editState.options
            .split(",")
            .map((o) => o.trim())
            .filter(Boolean)
        : null;

      const payload = {
        field_type: editState.field_type,
        label: editState.label.trim(),
        placeholder: editState.placeholder.trim() || null,
        required: editState.required,
        options: optionsArray,
        is_knockout: editState.is_knockout,
        knockout_answer:
          editState.is_knockout ? editState.knockout_answer.trim() || null : null,
      };

      const { data, error } = await (supabase as any)
        .from("job_form_fields")
        .update(payload)
        .eq("id", id)
        .select("*")
        .single();

      if (error) throw error;

      setFields((prev) => prev.map((f) => (f.id === id ? (data as FormField) : f)));
      setEditingId(null);
      toast.success("Field updated");
    } catch {
      toast.error("Failed to update field");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="mt-3">
      <CollapsibleTrigger className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground hover:text-foreground transition-colors w-full">
        <ChevronDown
          className={`h-3 w-3 transition-transform ${open ? "" : "-rotate-90"}`}
        />
        <FormInput className="h-3 w-3" />
        Application Form Fields
        {loaded && fields.length > 0 && (
          <span className="ml-1 bg-muted text-muted-foreground rounded-full px-1.5 py-0.5 text-[10px] font-normal">
            {fields.length}
          </span>
        )}
      </CollapsibleTrigger>

      <CollapsibleContent className="mt-3">
        <div className="rounded-lg border border-border bg-muted/20 p-3 space-y-3">
          {loading ? (
            <div className="space-y-2">
              {[0, 1, 2].map((i) => (
                <Skeleton key={i} className="h-10 w-full rounded-md" />
              ))}
            </div>
          ) : (
            <>
              {/* Field list */}
              {fields.length === 0 && !showAddForm && (
                <p className="text-xs text-muted-foreground text-center py-3">
                  No custom fields yet. Add fields to collect additional info from applicants.
                </p>
              )}

              {fields.map((field, idx) => (
                <div
                  key={field.id}
                  className="rounded-md border border-border bg-background p-3 space-y-2"
                >
                  {editingId === field.id ? (
                    <FieldForm
                      state={editState}
                      onChange={setEditState}
                      onSave={() => handleSaveEdit(field.id)}
                      onCancel={() => setEditingId(null)}
                      saving={saving}
                      mode="edit"
                    />
                  ) : (
                    <div className="flex items-start gap-2">
                      {/* Reorder buttons */}
                      <div className="flex flex-col gap-0.5 shrink-0 mt-0.5">
                        <button
                          onClick={() => handleMove(field.id, "up")}
                          disabled={idx === 0 || !!movingId}
                          className="text-muted-foreground hover:text-foreground disabled:opacity-30 transition-colors"
                          aria-label="Move field up"
                        >
                          <ChevronUp className="h-3.5 w-3.5" />
                        </button>
                        <button
                          onClick={() => handleMove(field.id, "down")}
                          disabled={idx === fields.length - 1 || !!movingId}
                          className="text-muted-foreground hover:text-foreground disabled:opacity-30 transition-colors"
                          aria-label="Move field down"
                        >
                          <ChevronDown className="h-3.5 w-3.5" />
                        </button>
                      </div>

                      {/* Field info */}
                      <div className="flex-1 min-w-0 space-y-1">
                        <div className="flex items-center gap-1.5 flex-wrap">
                          <span className="text-sm font-medium truncate">{field.label}</span>
                          <Badge variant="outline" className="text-[10px] px-1.5 py-0">
                            {FIELD_TYPE_LABELS[field.field_type]}
                          </Badge>
                          {field.required && (
                            <Badge variant="outline" className="text-[10px] px-1.5 py-0 border-amber-400/50 text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20">
                              Required
                            </Badge>
                          )}
                          {field.is_knockout && (
                            <Badge variant="outline" className="text-[10px] px-1.5 py-0 border-red-400/50 text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20">
                              Knockout
                            </Badge>
                          )}
                        </div>
                        {field.placeholder && (
                          <p className="text-[11px] text-muted-foreground truncate">
                            Placeholder: {field.placeholder}
                          </p>
                        )}
                        {field.options && field.options.length > 0 && (
                          <p className="text-[11px] text-muted-foreground truncate">
                            Options: {field.options.join(", ")}
                          </p>
                        )}
                        {field.is_knockout && field.knockout_answer && (
                          <p className="text-[11px] text-red-600 dark:text-red-400">
                            Disqualify if answer = "{field.knockout_answer}"
                          </p>
                        )}
                      </div>

                      {/* Actions */}
                      <div className="flex items-center gap-1 shrink-0">
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-6 w-6 text-muted-foreground hover:text-foreground"
                          onClick={() => startEdit(field)}
                          title="Edit field"
                        >
                          <GripVertical className="h-3.5 w-3.5" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-6 w-6 text-muted-foreground hover:text-destructive"
                          onClick={() => handleDelete(field.id)}
                          disabled={deletingId === field.id}
                          title="Delete field"
                        >
                          {deletingId === field.id ? (
                            <Loader2 className="h-3.5 w-3.5 animate-spin" />
                          ) : (
                            <Trash2 className="h-3.5 w-3.5" />
                          )}
                        </Button>
                      </div>
                    </div>
                  )}
                </div>
              ))}

              {/* Add field form */}
              {showAddForm ? (
                <div className="rounded-md border border-primary/30 bg-primary/5 p-3">
                  <FieldForm
                    state={addState}
                    onChange={setAddState}
                    onSave={handleAdd}
                    onCancel={() => {
                      setShowAddForm(false);
                      setAddState(DEFAULT_ADD_STATE);
                    }}
                    saving={saving}
                    mode="add"
                  />
                </div>
              ) : (
                <Button
                  variant="outline"
                  size="sm"
                  className="h-7 text-xs gap-1 w-full"
                  onClick={() => setShowAddForm(true)}
                >
                  <Plus className="h-3.5 w-3.5" />
                  Add Field
                </Button>
              )}
            </>
          )}
        </div>
      </CollapsibleContent>
    </Collapsible>
  );
}

// ─── Reusable field form (add + edit) ────────────────────────────────────────

interface FieldFormProps {
  state: AddFieldFormState;
  onChange: (s: AddFieldFormState) => void;
  onSave: () => void;
  onCancel: () => void;
  saving: boolean;
  mode: "add" | "edit";
}

function FieldForm({ state, onChange, onSave, onCancel, saving, mode }: FieldFormProps) {
  const needsOptions = FIELD_TYPES_WITH_OPTIONS.includes(state.field_type);

  const set = (key: keyof AddFieldFormState, value: string | boolean) =>
    onChange({ ...state, [key]: value });

  return (
    <div className="space-y-3">
      {/* Row 1: type + label */}
      <div className="grid grid-cols-2 gap-2">
        <div className="space-y-1">
          <Label className="text-xs">Field Type</Label>
          <Select
            value={state.field_type}
            onValueChange={(v) => set("field_type", v as FieldType)}
          >
            <SelectTrigger className="h-8 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {(Object.keys(FIELD_TYPE_LABELS) as FieldType[]).map((t) => (
                <SelectItem key={t} value={t} className="text-xs">
                  {FIELD_TYPE_LABELS[t]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-1">
          <Label className="text-xs">Label *</Label>
          <Input
            value={state.label}
            onChange={(e) => set("label", e.target.value)}
            placeholder="e.g. Years of experience"
            className="h-8 text-xs"
          />
        </div>
      </div>

      {/* Placeholder */}
      <div className="space-y-1">
        <Label className="text-xs">Placeholder</Label>
        <Input
          value={state.placeholder}
          onChange={(e) => set("placeholder", e.target.value)}
          placeholder="Optional helper text shown inside the field"
          className="h-8 text-xs"
        />
      </div>

      {/* Options for select/multiselect */}
      {needsOptions && (
        <div className="space-y-1">
          <Label className="text-xs">Options * (comma-separated)</Label>
          <Input
            value={state.options}
            onChange={(e) => set("options", e.target.value)}
            placeholder="e.g. 0-1 years, 1-3 years, 3-5 years, 5+ years"
            className="h-8 text-xs"
          />
        </div>
      )}

      {/* Required toggle */}
      <div className="flex items-center gap-2">
        <Switch
          id={`req-${mode}`}
          checked={state.required}
          onCheckedChange={(v) => set("required", v)}
          className="scale-75"
        />
        <Label htmlFor={`req-${mode}`} className="text-xs cursor-pointer">
          Required field
        </Label>
      </div>

      {/* Knockout toggle */}
      <div className="flex items-center gap-2">
        <Switch
          id={`ko-${mode}`}
          checked={state.is_knockout}
          onCheckedChange={(v) => set("is_knockout", v)}
          className="scale-75"
        />
        <Label htmlFor={`ko-${mode}`} className="text-xs cursor-pointer">
          Knockout question (auto-disqualify if answer matches)
        </Label>
      </div>

      {/* Knockout answer */}
      {state.is_knockout && (
        <div className="space-y-1">
          <Label className="text-xs">
            Disqualify when answer equals *
          </Label>
          <Input
            value={state.knockout_answer}
            onChange={(e) => set("knockout_answer", e.target.value)}
            placeholder="e.g. No"
            className="h-8 text-xs border-red-300 dark:border-red-700"
          />
          <p className="text-[10px] text-muted-foreground">
            Applicant will be auto-rejected if their response exactly matches this value.
          </p>
        </div>
      )}

      {/* Actions */}
      <div className="flex items-center gap-2 pt-1">
        <Button
          size="sm"
          className="h-7 text-xs gap-1"
          onClick={onSave}
          disabled={saving}
        >
          {saving ? <Loader2 className="h-3 w-3 animate-spin" /> : null}
          {mode === "add" ? "Add Field" : "Save Changes"}
        </Button>
        <Button
          variant="ghost"
