  );
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Skeleton } from "@/components/ui/skeleton";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { toast } from "sonner";
import { ChevronDown, Mail, CheckCircle2, Loader2 } from "lucide-react";

interface AutoAckSettingsProps {
  jobId: string;
}

export default function AutoAckSettings({ jobId }: AutoAckSettingsProps) {
  const [open, setOpen] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [saving, setSaving] = useState(false);

  const [enabled, setEnabled] = useState(true);
  const [subject, setSubject] = useState("Thank you for your application!");
  const [body, setBody] = useState(
    "Thank you for applying to {{job_title}}. We have received your application and will review it shortly. We will be in touch if your profile matches our requirements."
  );

  useEffect(() => {
    if (!open || loaded) return;

    let cancelled = false;
    (async () => {
      const { data } = await (supabase as any)
        .from("jobs")
        .select("auto_ack_enabled, auto_ack_subject, auto_ack_body")
        .eq("id", jobId)
        .single();

      if (!cancelled && data) {
        setEnabled(data.auto_ack_enabled ?? true);
        setSubject(
          data.auto_ack_subject ?? "Thank you for your application!"
        );
        setBody(
          data.auto_ack_body ??
            "Thank you for applying to {{job_title}}. We have received your application and will review it shortly. We will be in touch if your profile matches our requirements."
        );
        setLoaded(true);
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [open, jobId, loaded]);

  const handleSave = async () => {
    if (!subject.trim()) {
      toast.error("Subject is required");
      return;
    }
    if (!body.trim()) {
      toast.error("Email body is required");
      return;
    }

    setSaving(true);
    try {
      const { error } = await (supabase as any)
        .from("jobs")
        .update({
          auto_ack_enabled: enabled,
          auto_ack_subject: subject.trim(),
          auto_ack_body: body.trim(),
        })
        .eq("id", jobId);

      if (error) throw error;
      toast.success("Auto-acknowledgement settings saved");
    } catch {
      toast.error("Failed to save settings");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="mt-3">
      <CollapsibleTrigger className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground hover:text-foreground transition-colors w-full">
        <ChevronDown
          className={`h-3 w-3 transition-transform ${open ? "" : "-rotate-90"}`}
        />
        <Mail className="h-3 w-3" />
        Auto-Acknowledgement Email
        {loaded && !enabled && (
          <span className="ml-1 bg-muted text-muted-foreground rounded-full px-1.5 py-0.5 text-[10px] font-normal">
            Off
          </span>
        )}
      </CollapsibleTrigger>

      <CollapsibleContent className="mt-3">
        <div className="rounded-lg border border-border bg-muted/20 p-3 space-y-3">
          {!loaded && open ? (
            <div className="space-y-2">
              <Skeleton className="h-6 w-full" />
              <Skeleton className="h-8 w-full" />
              <Skeleton className="h-20 w-full" />
            </div>
          ) : (
            <>
              {/* Enable toggle */}
              <div className="flex items-center gap-2">
                <Switch
                  id="auto-ack-toggle"
                  checked={enabled}
                  onCheckedChange={setEnabled}
                  className="scale-75"
                />
                <Label htmlFor="auto-ack-toggle" className="text-xs cursor-pointer">
                  Send acknowledgement email to applicants
                </Label>
              </div>

              {enabled && (
                <>
                  {/* Subject */}
                  <div className="space-y-1">
                    <Label className="text-xs">
                      Subject{" "}
                      <span className="text-muted-foreground font-normal">
                        — use{" "}
                        <code className="font-mono text-[11px] bg-muted px-1 rounded">
                          {"{{job_title}}"}
                        </code>
                      </span>
                    </Label>
                    <Input
                      value={subject}
                      onChange={(e) => setSubject(e.target.value)}
                      placeholder="Thank you for your application!"
                      className="h-8 text-xs"
                    />
                  </div>

                  {/* Body */}
                  <div className="space-y-1">
                    <Label className="text-xs">
                      Email Body{" "}
                      <span className="text-muted-foreground font-normal">
                        — variables:{" "}
                        <code className="font-mono text-[11px] bg-muted px-1 rounded">
                          {"{{job_title}}"}
                        </code>{" "}
                        <code className="font-mono text-[11px] bg-muted px-1 rounded">
                          {"{{candidate_name}}"}
                        </code>
                      </span>
                    </Label>
                    <Textarea
                      value={body}
                      onChange={(e) => setBody(e.target.value)}
                      rows={5}
                      className="text-xs resize-none"
                      placeholder="Write your acknowledgement message here…"
                    />
                  </div>
                </>
              )}

              <Button
                size="sm"
                className="h-7 text-xs gap-1"
                onClick={handleSave}
                disabled={saving}
              >
                {saving ? (
                  <Loader2 className="h-3 w-3 animate-spin" />
                ) : (
                  <CheckCircle2 className="h-3 w-3" />
                )}
                Save Settings
              </Button>
            </>
          )}
        </div>
      </CollapsibleContent>
    </Collapsible>
  );
}

