      return row as JobInfo;
    },
    enabled: !!jobId,
    retry: 1,
    staleTime: 60_000,
  });

  // Fetch custom form fields for this job (anon-accessible via RLS policy)
  const { data: formFields = [] } = useQuery<JobFormField[]>({
    queryKey: ["apply-form-fields", jobId],
    queryFn: async () => {
      if (!jobId) return [];
      const { data, error } = await (supabase as any)
        .from("job_form_fields")
        .select("id, field_type, label, placeholder, required, options, sort_order, is_knockout, knockout_answer")
        .eq("job_id", jobId)
        .order("sort_order", { ascending: true });
      if (error) return [];
      return (data ?? []) as JobFormField[];
    },
    enabled: !!jobId,
    staleTime: 60_000,
  });

