// ── Custom Field Input renderer ─────────────────────────────────────────────

interface CustomFieldInputProps {
  field: JobFormField;
  value: string | boolean | string[] | undefined;
  onChange: (val: string | boolean | string[]) => void;
  error?: string;
  disabled: boolean;
}

function CustomFieldInput({
  field,
  value,
  onChange,
  error,
  disabled,
}: CustomFieldInputProps) {
  const fieldId = `custom-${field.id}`;
  const strVal = typeof value === "string" ? value : "";
  const boolVal = typeof value === "boolean" ? value : false;
  const arrVal = Array.isArray(value) ? value : [];

  return (
    <div className="space-y-1.5">
      <Label htmlFor={fieldId}>
        {field.label}
        {field.required && <span className="text-destructive ml-1">*</span>}
      </Label>

      {field.field_type === "text" && (
        <Input
          id={fieldId}
          type="text"
          placeholder={field.placeholder ?? ""}
          value={strVal}
          onChange={(e) => onChange(e.target.value)}
          aria-invalid={!!error}
          disabled={disabled}
        />
      )}

      {field.field_type === "number" && (
        <Input
          id={fieldId}
          type="number"
          placeholder={field.placeholder ?? ""}
          value={strVal}
          onChange={(e) => onChange(e.target.value)}
          aria-invalid={!!error}
          disabled={disabled}
        />
      )}

      {field.field_type === "url" && (
        <Input
          id={fieldId}
          type="url"
          placeholder={field.placeholder ?? "https://"}
          value={strVal}
          onChange={(e) => onChange(e.target.value)}
          aria-invalid={!!error}
          disabled={disabled}
        />
      )}

      {field.field_type === "date" && (
        <Input
          id={fieldId}
          type="date"
          value={strVal}
          onChange={(e) => onChange(e.target.value)}
          aria-invalid={!!error}
          disabled={disabled}
        />
      )}

      {field.field_type === "textarea" && (
        <Textarea
          id={fieldId}
          placeholder={field.placeholder ?? ""}
          value={strVal}
          onChange={(e) => onChange(e.target.value)}
          aria-invalid={!!error}
          disabled={disabled}
          rows={4}
          className="resize-none"
        />
      )}

      {field.field_type === "checkbox" && (
        <div className="flex items-center gap-2">
          <Checkbox
            id={fieldId}
            checked={boolVal}
            onCheckedChange={(checked) => onChange(!!checked)}
            aria-invalid={!!error}
            disabled={disabled}
          />
          <Label htmlFor={fieldId} className="text-sm font-normal cursor-pointer">
            {field.placeholder ?? "Yes"}
          </Label>
        </div>
      )}

      {field.field_type === "select" && (
        <Select
          value={strVal}
          onValueChange={onChange}
          disabled={disabled}
        >
          <SelectTrigger id={fieldId} aria-invalid={!!error}>
            <SelectValue placeholder={field.placeholder ?? "Select an option"} />
          </SelectTrigger>
          <SelectContent>
            {(field.options ?? []).map((opt) => (
              <SelectItem key={opt} value={opt}>
                {opt}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      )}

      {field.field_type === "multiselect" && (
        <div className="space-y-1.5">
          {(field.options ?? []).map((opt) => (
            <div key={opt} className="flex items-center gap-2">
              <Checkbox
                id={`${fieldId}-${opt}`}
                checked={arrVal.includes(opt)}
                onCheckedChange={(checked) => {
                  if (checked) {
                    onChange([...arrVal, opt]);
                  } else {
                    onChange(arrVal.filter((v) => v !== opt));
                  }
                }}
                disabled={disabled}
              />
              <Label
                htmlFor={`${fieldId}-${opt}`}
                className="text-sm font-normal cursor-pointer"
              >
                {opt}
              </Label>
            </div>
          ))}
        </div>
      )}

      {error && (
        <p className="text-xs text-destructive" role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

