  const queryClient = useQueryClient();
  const [updatingId, setUpdatingId] = useState<string | null>(null);
  const [hideDisqualified, setHideDisqualified] = useState(false);
  const [expandedCustomFields, setExpandedCustomFields] = useState<Set<string>>(new Set());

  const {
    data: applications,
    isLoading,
    error,
  } = useQuery<Application[]>({
    queryKey: ["applications", jobId],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("applications")
        .select(
          "id, job_id, name, email, phone, linkedin_url, resume_path, resume_filename, status, created_at, custom_fields, auto_disqualified, disqualify_reason"
        )
        .eq("job_id", jobId)
        .order("created_at", { ascending: false });
      if (error) throw new Error(error.message);
      return (data ?? []) as Application[];
    },
    enabled: !!jobId,
    staleTime: 30_000,
  });

